const hub=document.createElement('dialog');hub.className='everyday-hub';hub.setAttribute('aria-labelledby','everydayTitle');hub.innerHTML='<div class="everyday-head"><div><h2 id="everydayTitle">Ruang alat & ide</h2><p style="margin:6px 0 0">38 alat untuk bekerja, berkarya, dan menjalani hari.</p></div><button class="study-button" id="closeEveryday" type="button" aria-label="Tutup pusat fitur">Tutup</button></div><div class="everyday-search"><i data-icon="search"></i><input id="everydaySearch" type="search" placeholder="Cari alat, misalnya gambar, tagihan, atau proyek…" aria-label="Cari alat dan fitur"><span class="everyday-item-meta">⌘ J</span></div><div class="everyday-filters" aria-label="Kategori alat"></div><div class="everyday-count" role="status" id="everydayCount"></div><div class="everyday-grid" id="everydayGrid"></div><p>Data alat pribadi disimpan di perangkat ini untuk akunmu. Generator sandi tidak menyimpan hasilnya.</p>';
document.body.append(hub);let category='Semua';const all=[...catalog,...oldTools];
function showHub(){hub.showModal();renderHub();hydrateIcons(hub);q('#everydaySearch').focus();}
function renderHub(){const filters=q('.everyday-filters');filters.textContent='';['Semua','Favorit',...new Set(all.map(t=>t[4]))].forEach(c=>{const b=document.createElement('button');b.type='button';b.textContent=c;b.className=category===c?'active':'';b.setAttribute('aria-pressed',String(category===c));b.onclick=()=>{category=c;renderHub();};filters.append(b);});const query=q('#everydaySearch').value.toLowerCase(),shown=all.filter(t=>(category==='Semua'||category==='Favorit'&&data.favorites.includes(t[0])||category===t[4])&&t.join(' ').toLowerCase().includes(query));q('#everydayCount').textContent=shown.length+' alat';const grid=q('#everydayGrid');grid.innerHTML=shown.map((t,i)=>`<article class="everyday-tile" style="--i:${Math.min(i,12)}"><button class="tool-card-open" data-everyday="${t[0]}"><i data-icon="${t[3]}"></i><strong>${t[1]}</strong><small>${t[2]}</small></button><button class="tool-favorite" data-favorite="${t[0]}" aria-label="Favorit: ${t[1]}" aria-pressed="${data.favorites.includes(t[0])}">${data.favorites.includes(t[0])?'★':'☆'}</button></article>`).join('')||'<p class="everyday-empty">Tidak ada alat yang cocok. Coba kata lain.</p>';grid.querySelectorAll('[data-everyday]').forEach(b=>b.onclick=()=>{hub.close();window.openStudyTool(b.dataset.everyday);});grid.querySelectorAll('[data-favorite]').forEach(b=>b.onclick=()=>{const id=b.dataset.favorite;data.favorites=data.favorites.includes(id)?data.favorites.filter(v=>v!==id):[...data.favorites,id];save();renderHub();});hydrateIcons(grid);}
q('#closeEveryday').onclick=()=>hub.close();q('#everydaySearch').oninput=renderHub;
const legacyStudyLibrary=window.openStudyLibrary;window.openStudyLibrary=showHub;['studyLaunch','studyTopLaunch','moreNav'].forEach(id=>{const b=q('#'+id);if(b)b.onclick=()=>{showHub();closeSidebar();};});q('#studyLaunch span').textContent='Alat & fitur';
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='j'){e.preventDefault();if(hub.open)hub.close();else showHub();}});
const aiHelpersButton=document.createElement('button');aiHelpersButton.type='button';aiHelpersButton.className='study-button';aiHelpersButton.textContent='Bantuan AI: menulis, meringkas, menerjemahkan';aiHelpersButton.onclick=()=>{hub.close();legacyStudyLibrary?.();};hub.querySelector('#everydayGrid').after(aiHelpersButton);
const renderers={};
function register(id,fn){renderers[id]=fn;window.registerWorkspaceTool(catalog.find(t=>t[0]===id),()=>{clean();clean=()=>{};activeTool=id;const body=q('#studyBody');body.classList.add('everyday-panel');fn(body);hydrateIcons(body);});}
function field(label,id,value='',type='text'){return `<div class="everyday-field"><label for="${id}">${label}</label><input id="${id}" type="${type}" value="${escape(value)}"></div>`;}
function textarea(label,id,value='',rows=5){return `<div class="everyday-field"><label for="${id}">${label}</label><textarea id="${id}" rows="${rows}">${escape(value)}</textarea></div>`;}
function select(label,id,options){return `<div class="everyday-field"><label for="${id}">${label}</label><select id="${id}">${options.map(o=>{const [value,title]=Array.isArray(o)?o:[o,o];return `<option value="${escape(value)}">${escape(title)}</option>`;}).join('')}</select></div>`;}
function btn(text,id,primary=false){return `<button class="study-button${primary?' primary':''}" type="button" id="${id}">${text}</button>`;}
function actions(...buttons){return '<div class="everyday-actions">'+buttons.join('')+'</div>';}
function result(){return '<div class="everyday-result" id="edResult" role="status" aria-live="polite"></div>';}
function val(id){return q('#'+id).value;}const num=id=>Number(val(id));const on=(id,fn,type='click')=>q('#'+id).addEventListener(type,fn);
function intro(body,text){body.innerHTML='<p class="everyday-panel-intro">'+text+'</p>';}
function textResult(s){q('#edResult').textContent=s;}function download(name,text,type='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function copy(text){try{await navigator.clipboard.writeText(text);showToast('Disalin.');}catch{showToast('Penyalinan belum diizinkan. Pilih teks dan salin secara manual.');}}
function bindList(container,items,renderer){container.innerHTML=items.length?items.map(renderer).join(''):'<p class="everyday-empty">Belum ada data. Tambahkan yang pertama.</p>';}
function removeAt(collection,index,rerender){collection.splice(index,1);save();rerender();}
register('kanban',body=>{intro(body,'Pindahkan pekerjaan dari rencana hingga selesai. Tersimpan di perangkat ini.');body.insertAdjacentHTML('beforeend',field('Pekerjaan','projectName')+actions(btn('Tambahkan','addProject',true))+'<div class="everyday-kanban" id="projectColumns"></div>');function list(){q('#projectColumns').innerHTML=['Rencana','Dikerjakan','Selesai'].map((name,status)=>'<section class="everyday-column"><h3>'+name+'</h3>'+data.projects.map((t,i)=>t.status===status?`<div class="everyday-task-card"><p>${escape(t.name)}</p><select aria-label="Status ${escape(t.name)}" data-project-status="${i}">${['Rencana','Dikerjakan','Selesai'].map((s,j)=>`<option value="${j}" ${j===status?'selected':''}>${s}</option>`).join('')}</select><button class="everyday-subtle-button" data-project-delete="${i}">Hapus</button></div>`:'').join('')+'</section>').join('');body.querySelectorAll('[data-project-status]').forEach(s=>s.onchange=()=>{data.projects[+s.dataset.projectStatus].status=Number(s.value);save();list();});body.querySelectorAll('[data-project-delete]').forEach(b=>b.onclick=()=>removeAt(data.projects,+b.dataset.projectDelete,list));}on('addProject',()=>{if(!val('projectName').trim())return showToast('Isi nama pekerjaan.');data.projects.push({id:uid(),name:val('projectName').trim().slice(0,200),status:0});save();q('#projectName').value='';list();});list();});
register('habits',body=>{intro(body,'Tandai kebiasaan per hari. Riwayat disimpan dengan tanggal lokal perangkatmu.');body.insertAdjacentHTML('beforeend',field('Kebiasaan','habitName')+actions(btn('Tambah kebiasaan','addHabit',true))+'<div class="everyday-table-wrap" id="habitGrid"></div>');const days=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);return {key:d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0'),label:d.toLocaleDateString('id-ID',{weekday:'short',day:'numeric'})};});function list(){q('#habitGrid').innerHTML='<table class="everyday-table everyday-habit-grid"><thead><tr><th>Kebiasaan</th>'+days.map(d=>'<th>'+d.label+'</th>').join('')+'<th></th></tr></thead><tbody>'+data.habits.map((h,i)=>'<tr><th>'+escape(h.name)+'<small>'+days.filter(d=>h.days?.[d.key]).length+'/7 hari</small></th>'+days.map(d=>`<td><input type="checkbox" data-habit="${i}" data-day="${d.key}" ${h.days?.[d.key]?'checked':''} aria-label="${escape(h.name)} ${d.key}"></td>`).join('')+`<td><button class="everyday-subtle-button" data-delete-habit="${i}">Hapus</button></td></tr>`).join('')+'</tbody></table>';body.querySelectorAll('[data-habit]').forEach(c=>c.onchange=()=>{const h=data.habits[+c.dataset.habit];h.days||={};h.days[c.dataset.day]=c.checked;save();list();});body.querySelectorAll('[data-delete-habit]').forEach(b=>b.onclick=()=>removeAt(data.habits,+b.dataset.deleteHabit,list));}on('addHabit',()=>{if(!val('habitName').trim())return;data.habits.push({name:val('habitName').trim().slice(0,100),days:{}});save();q('#habitName').value='';list();});list();});
register('shopping',body=>{intro(body,'Buat daftar barang dan perkiraan biaya. Tandai saat sudah dibeli.');body.insertAdjacentHTML('beforeend',field('Barang','shoppingName')+'<div class="everyday-row">'+field('Jumlah','shoppingQty',1,'number')+field('Harga per barang (Rp)','shoppingPrice',0,'number')+'</div>'+actions(btn('Tambah barang','addShopping',true),btn('Unduh daftar','exportShopping'))+result()+'<div id="shoppingList"></div>');function list(){const total=data.shopping.reduce((s,i)=>s+i.qty*i.price,0),left=data.shopping.filter(i=>!i.done).reduce((s,i)=>s+i.qty*i.price,0);textResult('Total perkiraan: '+money(total)+' · Belum dibeli: '+money(left));bindList(q('#shoppingList'),data.shopping,(t,i)=>`<div class="everyday-list-item ${t.done?'done':''}"><input type="checkbox" data-shopping="${i}" ${t.done?'checked':''} aria-label="Sudah membeli ${escape(t.name)}"><span>${escape(t.name)}<small>${t.qty} × ${money(t.price)} = ${money(t.qty*t.price)}</small></span><button class="everyday-subtle-button" data-remove-shopping="${i}" aria-label="Hapus ${escape(t.name)}">×</button></div>`);body.querySelectorAll('[data-shopping]').forEach(c=>c.onchange=()=>{data.shopping[+c.dataset.shopping].done=c.checked;save();list();});body.querySelectorAll('[data-remove-shopping]').forEach(b=>b.onclick=()=>removeAt(data.shopping,+b.dataset.removeShopping,list));}on('addShopping',()=>{if(!val('shoppingName').trim()||num('shoppingQty')<=0||num('shoppingPrice')<0)return showToast('Isi barang, jumlah positif, dan harga tidak negatif.');data.shopping.push({name:val('shoppingName').trim().slice(0,150),qty:num('shoppingQty'),price:num('shoppingPrice'),done:false});save();q('#shoppingName').value='';list();});on('exportShopping',()=>download('daftar-belanja.txt',data.shopping.map(t=>(t.done?'[x] ':'[ ] ')+t.name+' · '+t.qty+' × '+money(t.price)).join('\n')));list();});
register('budget',body=>{intro(body,'Catat arus uang pribadi. Angka ini dihitung dari catatanmu sendiri.');body.insertAdjacentHTML('beforeend',field('Keterangan','budgetName')+'<div class="everyday-row">'+select('Jenis','budgetType',[['income','Pemasukan'],['expense','Pengeluaran']])+field('Jumlah (Rp)','budgetAmount','','number')+'</div>'+field('Tanggal','budgetDate',today(),'date')+actions(btn('Simpan transaksi','addBudget',true),btn('Ekspor CSV','exportBudget'))+result()+'<div id="budgetList"></div>');function list(){const income=data.transactions.filter(t=>t.type==='income').reduce((s,t)=>s+t.amount,0),expense=data.transactions.filter(t=>t.type==='expense').reduce((s,t)=>s+t.amount,0);q('#edResult').innerHTML='<strong>'+money(income-expense)+'</strong><p>Pemasukan '+money(income)+' · Pengeluaran '+money(expense)+'</p>';bindList(q('#budgetList'),data.transactions,(t,i)=>`<div class="everyday-list-item"><span>${escape(t.name)}<small>${escape(t.date)} · ${t.type==='income'?'+':'−'}${money(t.amount)}</small></span><button class="everyday-subtle-button" data-budget-remove="${i}">Hapus</button></div>`);body.querySelectorAll('[data-budget-remove]').forEach(b=>b.onclick=()=>removeAt(data.transactions,+b.dataset.budgetRemove,list));}on('addBudget',()=>{if(!val('budgetName').trim()||num('budgetAmount')<=0||!val('budgetDate'))return showToast('Isi keterangan, tanggal, dan jumlah positif.');data.transactions.push({name:val('budgetName').trim().slice(0,150),type:val('budgetType'),amount:num('budgetAmount'),date:val('budgetDate')});save();q('#budgetName').value='';q('#budgetAmount').value='';list();});on('exportBudget',()=>download('catatan-keuangan.csv',writeCSV([['Tanggal','Keterangan','Jenis','Jumlah'],...data.transactions.map(t=>[t.date,t.name,t.type,t.amount])]),'text/csv;charset=utf-8'));list();});
register('savings',body=>{intro(body,'Tentukan target dan saldo yang sudah terkumpul. Perhitungan ini tidak terhubung ke rekening.');body.insertAdjacentHTML('beforeend',field('Nama target','goalName')+'<div class="everyday-row">'+field('Target (Rp)','goalTarget','','number')+field('Terkumpul (Rp)','goalCurrent',0,'number')+'</div>'+actions(btn('Simpan target','addGoal',true))+'<div id="goalsList"></div>');function list(){bindList(q('#goalsList'),data.goals,(t,i)=>`<section class="study-card"><h3>${escape(t.name)}</h3><p>${money(t.current)} dari ${money(t.target)}</p><div class="everyday-progress"><i style="width:${Math.min(100,t.current/t.target*100)}%"></i></div><small>${number(t.current/t.target*100)}% · Sisa ${money(Math.max(0,t.target-t.current))}</small><div class="everyday-actions"><button class="study-button" data-goal-edit="${i}">Ubah saldo</button><button class="everyday-subtle-button" data-goal-remove="${i}">Hapus</button></div></section>`);body.querySelectorAll('[data-goal-remove]').forEach(b=>b.onclick=()=>removeAt(data.goals,+b.dataset.goalRemove,list));body.querySelectorAll('[data-goal-edit]').forEach(b=>b.onclick=()=>{const i=+b.dataset.goalEdit,t=data.goals[i];q('#goalName').value=t.name;q('#goalTarget').value=t.target;q('#goalCurrent').value=t.current;q('#addGoal').dataset.edit=i;q('#addGoal').textContent='Perbarui target';q('#goalCurrent').focus();});}on('addGoal',()=>{if(!val('goalName').trim()||num('goalTarget')<=0||num('goalCurrent')<0)return showToast('Isi target positif dan saldo tidak negatif.');const item={name:val('goalName').trim().slice(0,100),target:num('goalTarget'),current:num('goalCurrent')};if(q('#addGoal').dataset.edit!==undefined){data.goals[+q('#addGoal').dataset.edit]=item;delete q('#addGoal').dataset.edit;q('#addGoal').textContent='Simpan target';}else data.goals.push(item);save();list();});list();});
register('split',body=>{intro(body,'Bagi jumlah akhir secara rata. Tambahkan biaya layanan dan penyesuaian yang kamu tentukan.');body.insertAdjacentHTML('beforeend',field('Subtotal (Rp)','splitSubtotal',100000,'number')+'<div class="everyday-row">'+field('Layanan (%)','splitService',0,'number')+field('Pajak (%)','splitTax',0,'number')+'</div>'+field('Jumlah orang','splitPeople',4,'number')+actions(btn('Hitung pembagian','splitCalculate',true))+result());function run(){const a=num('splitSubtotal'),s=num('splitService'),t=num('splitTax'),p=num('splitPeople');if(a<0||s<0||t<0||!Number.isInteger(p)||p<1)return textResult('Masukkan nilai tidak negatif dan jumlah orang bulat minimal 1.');const total=a*(1+(s+t)/100);q('#edResult').innerHTML='<strong>'+money(total/p)+'/orang</strong><p>Total '+money(total)+' · Pajak dan layanan dihitung dari subtotal.</p><p>Jika dibulatkan ke rupiah: '+(total%p?money(Math.floor(total/p))+' per orang, dengan sisa pembulatan '+money(total-Math.floor(total/p)*p):money(total/p)+' per orang')+'.</p>';}on('splitCalculate',run);run();});
register('discount',body=>{intro(body,'Hitung diskon berurutan dan pajak setelah diskon.');body.insertAdjacentHTML('beforeend',field('Harga awal (Rp)','discountPrice',200000,'number')+'<div class="everyday-row">'+field('Diskon pertama (%)','discountOne',20,'number')+field('Diskon kedua (%)','discountTwo',10,'number')+'</div>'+field('Pajak setelah diskon (%)','discountTax',0,'number')+actions(btn('Hitung harga','discountCalculate',true))+result());function run(){const p=num('discountPrice'),a=num('discountOne'),b=num('discountTwo'),t=num('discountTax');if(p<0||a<0||a>100||b<0||b>100||t<0)return textResult('Diskon harus 0–100%, harga dan pajak tidak negatif.');const net=p*(1-a/100)*(1-b/100),total=net*(1+t/100);q('#edResult').innerHTML='<strong>'+money(total)+'</strong><p>Sesudah diskon '+money(net)+' · Hemat sebelum pajak '+money(p-net)+'</p><p>Diskon berurutan efektif: '+number((1-(1-a/100)*(1-b/100))*100)+'%.</p>';}on('discountCalculate',run);run();});
register('meeting',body=>{intro(body,'Susun agenda dan notulen. Hasilnya bisa disalin atau diunduh tanpa mengirim ke orang lain.');body.insertAdjacentHTML('beforeend',field('Judul rapat','meetingTitle')+field('Tanggal','meetingDate',today(),'date')+textarea('Agenda (satu poin per baris)','meetingAgenda')+textarea('Hasil & keputusan','meetingDecisions')+textarea('Tindak lanjut (tugas — penanggung jawab — tenggat)','meetingActions')+actions(btn('Simpan notulen','saveMeeting',true),btn('Salin','copyMeeting'),btn('Unduh .txt','downloadMeeting'))+'<div id="meetingList"></div>');function draft(){return val('meetingTitle')+'\n'+val('meetingDate')+'\n\nAGENDA\n'+val('meetingAgenda')+'\n\nKEPUTUSAN\n'+val('meetingDecisions')+'\n\nTINDAK LANJUT\n'+val('meetingActions');}function list(){bindList(q('#meetingList'),data.meetings,(m,i)=>`<div class="everyday-list-item"><span>${escape(m.title)}<small>${escape(m.date)}</small></span><button class="study-button" data-meeting-load="${i}">Buka</button><button class="everyday-subtle-button" data-meeting-delete="${i}">Hapus</button></div>`);body.querySelectorAll('[data-meeting-load]').forEach(b=>b.onclick=()=>{const m=data.meetings[+b.dataset.meetingLoad];for(const [id,k]of [['meetingTitle','title'],['meetingDate','date'],['meetingAgenda','agenda'],['meetingDecisions','decisions'],['meetingActions','actions']])q('#'+id).value=m[k];q('#saveMeeting').dataset.edit=b.dataset.meetingLoad;});body.querySelectorAll('[data-meeting-delete]').forEach(b=>b.onclick=()=>removeAt(data.meetings,+b.dataset.meetingDelete,list));}on('saveMeeting',()=>{if(!val('meetingTitle').trim())return showToast('Isi judul rapat.');const m={title:val('meetingTitle').trim(),date:val('meetingDate'),agenda:val('meetingAgenda'),decisions:val('meetingDecisions'),actions:val('meetingActions')};if(q('#saveMeeting').dataset.edit!==undefined)data.meetings[+q('#saveMeeting').dataset.edit]=m;else{data.meetings.push(m);q('#saveMeeting').dataset.edit=data.meetings.length-1;}save();list();showToast('Notulen tersimpan.');});on('copyMeeting',()=>copy(draft()));on('downloadMeeting',()=>download('notulen-rapat.txt',draft()));list();});
register('decide',body=>{intro(body,'Bandingkan opsi dengan kriteria yang kamu tentukan. Skor dihitung, bukan keputusan otomatis.');body.insertAdjacentHTML('beforeend',textarea('Pilihan (satu per baris)','decisionOptions','Pilihan A\nPilihan B',3)+textarea('Kriteria | bobot (satu per baris)','decisionCriteria','Biaya | 3\nKemudahan | 2\nManfaat | 4',4)+actions(btn('Buat matriks','buildMatrix',true))+'<div id="decisionMatrix"></div>'+result());let options=[],criteria=[];function calculate(){let scores=options.map((o,i)=>({name:o,score:criteria.reduce((s,c,j)=>s+Number(q(`#decisionScore${i}_${j}`).value||0)*c.weight,0)})).sort((a,b)=>b.score-a.score);textResult(scores.map((s,i)=>(i+1)+'. '+s.name+': '+number(s.score)+' poin').join(' · '));}on('buildMatrix',()=>{options=val('decisionOptions').split('\n').map(s=>s.trim()).filter(Boolean).slice(0,6);criteria=val('decisionCriteria').split('\n').filter(s=>s.trim()).slice(0,8).map(s=>{const [name,weight]=s.split('|');return {name:name.trim(),weight:Number(weight)};});if(options.length<2||!criteria.length||criteria.some(c=>!c.name||!Number.isFinite(c.weight)||c.weight<=0))return showToast('Isi minimal 2 opsi dan kriteria dengan bobot positif.');q('#decisionMatrix').innerHTML='<p class="everyday-panel-intro">Beri nilai 0–5; nilai 5 selalu berarti paling baik, termasuk untuk kriteria biaya.</p><div class="everyday-table-wrap"><table class="everyday-table"><thead><tr><th>Pilihan</th>'+criteria.map(c=>'<th>'+escape(c.name)+' (×'+c.weight+')</th>').join('')+'</tr></thead><tbody>'+options.map((o,i)=>'<tr><th>'+escape(o)+'</th>'+criteria.map((c,j)=>`<td><input type="number" id="decisionScore${i}_${j}" min="0" max="5" step="1" value="3" aria-label="${escape(o)}: ${escape(c.name)}"></td>`).join('')+'</tr>').join('')+'</tbody></table></div>';q('#decisionMatrix').oninput=e=>{if(e.target.type==='number'){e.target.value=Math.max(0,Math.min(5,Number(e.target.value)));calculate();}};calculate();});q('#buildMatrix').click();});
const zones=[['Asia/Jakarta','Jakarta'],['Asia/Makassar','Makassar'],['Asia/Jayapura','Jayapura'],['Asia/Singapore','Singapura'],['Asia/Tokyo','Tokyo'],['Asia/Dubai','Dubai'],['Europe/London','London'],['Europe/Paris','Paris'],['America/New_York','New York'],['America/Los_Angeles','Los Angeles'],['Australia/Sydney','Sydney'],['Pacific/Auckland','Auckland'],['UTC','UTC']];
register('worldclock',body=>{intro(body,'Waktu diperbarui dari jam perangkat. Zona waktu menyesuaikan aturan waktu musim panas bila berlaku.');const chosen=[...new Set(data.clockZones||['Asia/Jakarta','Europe/London','America/New_York'])];body.insertAdjacentHTML('beforeend',select('Tambah kota','clockZone',zones)+actions(btn('Tambah kota','addClock'))+'<div id="clockList"></div>');function tick(){q('#clockList').innerHTML=chosen.map((z,i)=>{const now=new Date(),time=now.toLocaleTimeString('id-ID',{timeZone:z,hour:'2-digit',minute:'2-digit',second:'2-digit'}),date=now.toLocaleDateString('id-ID',{timeZone:z,weekday:'long',day:'numeric',month:'short'});return `<div class="everyday-clock-card"><div class="everyday-row"><strong>${escape(zones.find(a=>a[0]===z)?.[1]||z)}</strong><button class="everyday-subtle-button" data-clock-remove="${i}" aria-label="Hapus jam ${escape(z)}">×</button></div><div class="everyday-clock">${time}</div><small>${date}</small></div>`;}).join('');body.querySelectorAll('[data-clock-remove]').forEach(b=>b.onclick=()=>{chosen.splice(+b.dataset.clockRemove,1);data.clockZones=chosen;save();tick();});}on('addClock',()=>{if(!chosen.includes(val('clockZone')))chosen.push(val('clockZone'));data.clockZones=chosen;save();tick();});tick();const interval=setInterval(tick,1000);clean=()=>clearInterval(interval);});
function zonedParts(timestamp,zone){const parts=new Intl.DateTimeFormat('en-CA',{timeZone:zone,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).formatToParts(new Date(timestamp));const p=Object.fromEntries(parts.map(p=>[p.type,p.value]));return [Number(p.year),Number(p.month),Number(p.day),Number(p.hour),Number(p.minute),Number(p.second)];}
function wallTime(date,time,zone,later=false){if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||!/^\d{2}:\d{2}$/.test(time))throw Error('Gunakan tanggal YYYY-MM-DD dan waktu HH:MM.');const [y,m,d]=date.split('-').map(Number),[h,min]=time.split(':').map(Number),target=Date.UTC(y,m-1,d,h,min);if(h>23||min>59||new Date(target).getUTCMonth()!==m-1||new Date(target).getUTCDate()!==d)throw Error('Tanggal atau waktu tidak valid.');const offsets=new Set([-36,0,36].map(hours=>{const t=target+hours*3600000,p=zonedParts(t,zone);return Date.UTC(p[0],p[1]-1,p[2],p[3],p[4],p[5])-t;}));const matches=[...offsets].map(off=>target-off).filter(t=>{const p=zonedParts(t,zone);return p[0]===y&&p[1]===m&&p[2]===d&&p[3]===h&&p[4]===min;}).sort((a,b)=>a-b);if(!matches.length)throw Error('Waktu ini tidak ada karena pergantian waktu musim panas. Pilih jam lain.');return {timestamp:matches[later?matches.length-1:0],ambiguous:matches.length>1};}
register('timezones',body=>{intro(body,'Konversikan tanggal dan jam dari satu kota ke kota lain.');body.insertAdjacentHTML('beforeend',field('Tanggal asal','zoneDate',today(),'date')+field('Jam asal (HH:MM, 24 jam)','zoneTime','09:00')+select('Zona asal','zoneFrom',zones)+select('Zona tujuan','zoneTo',zones)+select('Saat jam terjadi dua kali (pergantian DST)','zoneAmbiguity',[['early','Kejadian lebih awal'],['late','Kejadian lebih akhir']])+actions(btn('Konversi waktu','convertZone',true))+result());q('#zoneTo').value='Europe/London';function run(){try{const {timestamp,ambiguous}=wallTime(val('zoneDate'),val('zoneTime'),val('zoneFrom'),val('zoneAmbiguity')==='late');textResult(new Date(timestamp).toLocaleString('id-ID',{timeZone:val('zoneTo'),dateStyle:'full',timeStyle:'short'})+' · '+val('zoneTo')+(ambiguous?' · Waktu asal ambigu; memakai kejadian '+(val('zoneAmbiguity')==='late'?'lebih akhir.':'lebih awal.'):'')+'\nUTC: '+new Date(timestamp).toISOString().replace('T',' ').slice(0,16));}catch(e){textResult(e.message);}}on('convertZone',run);run();});
let countdown={end:0,left:300,running:false},stopwatch={start:0,elapsed:0,running:false,laps:[]};
const duration=ms=>{const seconds=Math.floor(Math.max(0,ms)/1000);return String(Math.floor(seconds/3600)).padStart(2,'0')+':'+String(Math.floor(seconds/60)%60).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0');};
setInterval(()=>{if(countdown.running&&Date.now()>=countdown.end){countdown.running=false;countdown.left=0;showToast('Hitung mundur selesai.');}},300);
register('countdown',body=>{intro(body,'Penghitung tetap berjalan saat panel ditutup selama halaman ini terbuka.');body.insertAdjacentHTML('beforeend',field('Durasi (menit)','countdownMinutes',5,'number')+'<div class="study-timer" id="countdownDisplay"></div>'+actions(btn('Mulai / jeda','countdownToggle',true),btn('Reset','countdownReset')));function tick(){const left=countdown.running?Math.max(0,countdown.end-Date.now()):countdown.left*1000;q('#countdownDisplay').textContent=duration(left);}on('countdownToggle',()=>{if(countdown.running){countdown.left=Math.max(0,(countdown.end-Date.now())/1000);countdown.running=false;}else{if(!countdown.left){const n=num('countdownMinutes');if(n<=0||n>1440)return showToast('Durasi harus 1–1440 menit.');countdown.left=n*60;}countdown.end=Date.now()+countdown.left*1000;countdown.running=true;}tick();});on('countdownReset',()=>{const n=num('countdownMinutes');if(n<=0||n>1440)return showToast('Durasi harus 1–1440 menit.');countdown.running=false;countdown.left=n*60;tick();});on('countdownMinutes',()=>{q('#countdownReset').click();},'change');tick();const interval=setInterval(tick,200);clean=()=>clearInterval(interval);});
register('stopwatch',body=>{intro(body,'Ukur waktu dengan jam monotonik perangkat. Tambahkan lap untuk menandai setiap putaran.');body.insertAdjacentHTML('beforeend','<div class="study-timer" style="font-size:45px" id="stopwatchDisplay"></div>'+actions(btn('Mulai / jeda','stopwatchToggle',true),btn('Catat lap','stopwatchLap'),btn('Reset','stopwatchReset'))+'<div id="stopwatchLaps"></div>');const elapsed=()=>stopwatch.elapsed+(stopwatch.running?performance.now()-stopwatch.start:0);function tick(){const ms=elapsed();q('#stopwatchDisplay').textContent=duration(ms)+'.'+String(Math.floor(ms%1000/10)).padStart(2,'0');}function laps(){q('#stopwatchLaps').innerHTML=stopwatch.laps.map((ms,i)=>'<div class="everyday-list-item"><span>Lap '+(i+1)+'</span><strong>'+duration(ms)+'.'+String(Math.floor(ms%1000/10)).padStart(2,'0')+'</strong></div>').join('');}on('stopwatchToggle',()=>{if(stopwatch.running){stopwatch.elapsed=elapsed();stopwatch.running=false;}else{stopwatch.start=performance.now();stopwatch.running=true;}tick();});on('stopwatchLap',()=>{if(!stopwatch.running)return showToast('Mulai stopwatch dahulu.');stopwatch.laps.push(elapsed());laps();});on('stopwatchReset',()=>{stopwatch={start:0,elapsed:0,running:false,laps:[]};tick();laps();});tick();laps();const interval=setInterval(tick,50);clean=()=>clearInterval(interval);});
register('breath',body=>{intro(body,'Ambil jeda singkat sesuai kenyamananmu. Ikuti lingkaran: tarik dan buang napas tanpa menahan.');body.insertAdjacentHTML('beforeend','<div class="breathing-orb" id="breathingOrb">Siap?</div><div style="text-align:center" id="breathProgress" role="status"></div>'+actions(btn('Mulai','startBreath',true),btn('Berhenti','stopBreath')));let interval=null,start=0;function stop(){clearInterval(interval);interval=null;q('#breathingOrb').classList.remove('inhale');q('#breathingOrb').textContent='Siap?';q('#breathProgress').textContent='';}on('startBreath',()=>{stop();start=Date.now();function tick(){const elapsed=(Date.now()-start)/1000,phase=Math.floor(elapsed/4)%2,cycles=Math.floor(elapsed/8);q('#breathingOrb').textContent=phase?'Buang napas':'Tarik napas';q('#breathingOrb').classList.toggle('inhale',phase===0);q('#breathProgress').textContent='Siklus '+(cycles+1)+' · '+(4-Math.floor(elapsed%4))+' detik';}tick();interval=setInterval(tick,200);});on('stopBreath',stop);clean=()=>clearInterval(interval);});
function randomInt(max){if(!Number.isSafeInteger(max)||max<1||max>0x100000000)throw Error('Rentang acak tidak valid.');const limit=Math.floor(0x100000000/max)*max,buffer=new Uint32Array(1);let value;do{crypto.getRandomValues(buffer);value=buffer[0];}while(value>=limit);return value%max;}
function shuffle(values){const a=[...values];for(let i=a.length-1;i>0;i--){const j=randomInt(i+1);[a[i],a[j]]=[a[j],a[i]];}return a;}
register('picker',body=>{intro(body,'Pilih dari daftar secara acak. Kamu bisa mencegah pilihan yang sama muncul kembali.');body.insertAdjacentHTML('beforeend',textarea('Pilihan (satu per baris)','pickerChoices','Baca buku\nJalan santai\nMenggambar')+field('Jumlah pilihan','pickerCount',1,'number')+'<label><input type="checkbox" id="pickerRemove"> Hapus hasil dari daftar setelah dipilih</label>'+actions(btn('Pilih sekarang','pickRandom',true))+result());on('pickRandom',()=>{const choices=val('pickerChoices').split('\n').map(x=>x.trim()).filter(Boolean),count=num('pickerCount');if(!choices.length||!Number.isInteger(count)||count<1||count>choices.length)return textResult('Isi daftar dan jumlah pilihan yang sesuai.');const picked=shuffle(choices.map((v,i)=>({v,i}))).slice(0,count);textResult(picked.map(v=>v.v).join(' · '));if(q('#pickerRemove').checked){const ids=new Set(picked.map(v=>v.i));q('#pickerChoices').value=choices.filter((v,i)=>!ids.has(i)).join('\n');}});});
function makePassword(length,groups){if(!Number.isInteger(length)||length<8||length>128||!groups.length)throw Error('Pilih minimal satu jenis karakter dan panjang 8–128.');const charset=groups.join('');return shuffle([...groups.map(g=>g[randomInt(g.length)]),...Array.from({length:length-groups.length},()=>charset[randomInt(charset.length)])]).join('');}
register('password',body=>{intro(body,'Hasil dibuat di browser menggunakan acak kriptografis. Sandi tidak disimpan atau dikirim ke AI.');body.insertAdjacentHTML('beforeend',field('Panjang sandi','passwordLength',20,'number')+'<div class="everyday-actions">'+[['lower','Huruf kecil'],['upper','Huruf besar'],['digits','Angka'],['symbols','Simbol']].map(([id,title])=>`<label><input type="checkbox" id="password${id}" checked> ${title}</label>`).join('')+'</div>'+actions(btn('Buat sandi','generatePassword',true),btn('Salin hasil','copyPassword'))+result());let password='';on('generatePassword',()=>{try{const groups=[['lower','abcdefghijkmnopqrstuvwxyz'],['upper','ABCDEFGHJKLMNPQRSTUVWXYZ'],['digits','23456789'],['symbols','!@#$%&*+-=?']].filter(([id])=>q('#password'+id).checked).map(a=>a[1]);password=makePassword(num('passwordLength'),groups);q('#edResult').classList.add('everyday-code');textResult(password);}catch(e){textResult(e.message);}});on('copyPassword',()=>{if(password)copy(password);else showToast('Buat sandi terlebih dahulu.');});});
register('text',body=>{intro(body,'Rapikan tulisan, hitung kata, dan ubah format tanpa mengirim teks ke server.');body.insertAdjacentHTML('beforeend',textarea('Teks','textSource','',10)+'<div class="everyday-toolbar">'+[['uppercase','HURUF BESAR'],['lowercase','huruf kecil'],['titlecase','Kapital Judul'],['trim','Rapikan spasi'],['dedupe','Hapus baris duplikat'],['sort','Urutkan baris'],['reverse','Balik urutan baris']].map(([id,title])=>`<button class="study-button" data-text-action="${id}">${title}</button>`).join('')+'</div>'+result()+actions(btn('Salin teks','copyText'),btn('Unduh .txt','downloadText')));function stats(){const text=val('textSource'),words=(text.match(/[\p{L}\p{N}]+(?:['’-][\p{L}\p{N}]+)*/gu)||[]).length;const characters=Array.from(text).length;textResult(words+' kata · '+characters+' karakter · '+(text?text.split('\n').length:0)+' baris · perkiraan baca '+Math.max(1,Math.ceil(words/200))+' menit.');}on('textSource',stats,'input');body.querySelectorAll('[data-text-action]').forEach(b=>b.onclick=()=>{let s=val('textSource');switch(b.dataset.textAction){case 'uppercase':s=s.toLocaleUpperCase('id-ID');break;case 'lowercase':s=s.toLocaleLowerCase('id-ID');break;case 'titlecase':s=s.toLocaleLowerCase('id-ID').replace(/\b\p{L}/gu,c=>c.toLocaleUpperCase('id-ID'));break;case 'trim':s=s.split('\n').map(l=>l.trim().replace(/[ \t]+/g,' ')).join('\n').trim();break;case 'dedupe':s=[...new Set(s.split('\n'))].join('\n');break;case 'sort':s=s.split('\n').sort((a,b)=>a.localeCompare(b,'id')).join('\n');break;case 'reverse':s=s.split('\n').reverse().join('\n');}q('#textSource').value=s;stats();});on('copyText',()=>copy(val('textSource')));on('downloadText',()=>download('teks.txt',val('textSource')));stats();});
register('json',body=>{intro(body,'Validasi JSON dan ubah tampilannya. Konten diproses di perangkatmu.');body.insertAdjacentHTML('beforeend',textarea('JSON','jsonSource','{"nama":"7 MIT","aktif":true}',10)+actions(btn('Rapikan','formatJSON',true),btn('Padatkan','minifyJSON'),btn('Salin','copyJSON'),btn('Unduh .json','downloadJSON'))+result());function run(spaces){try{const parsed=JSON.parse(val('jsonSource'));q('#jsonSource').value=JSON.stringify(parsed,null,spaces);textResult('JSON valid · Tipe nilai utama: '+(Array.isArray(parsed)?'array':parsed===null?'null':typeof parsed));}catch(e){textResult('JSON belum valid: '+e.message);}}on('formatJSON',()=>run(2));on('minifyJSON',()=>run(0));on('copyJSON',()=>copy(val('jsonSource')));on('downloadJSON',()=>{try{JSON.parse(val('jsonSource'));download('data.json',val('jsonSource'),'application/json');}catch{showToast('Perbaiki JSON sebelum mengunduh.');}});run(2);});
function encodeBase64(text){const bytes=new TextEncoder().encode(text);let s='';for(const b of bytes)s+=String.fromCharCode(b);return btoa(s);}
function decodeBase64(text){const s=atob(text),bytes=Uint8Array.from(s,c=>c.charCodeAt(0));return new TextDecoder('utf-8',{fatal:true}).decode(bytes);}
register('url',body=>{intro(body,'Konversi teks untuk URL atau Base64. Base64 adalah encoding, bukan enkripsi.');body.insertAdjacentHTML('beforeend',select('Operasi','encodingMode',[['uriEncode','URL encode'],['uriDecode','URL decode'],['b64Encode','Base64 encode (UTF-8)'],['b64Decode','Base64 decode (UTF-8)']])+textarea('Teks sumber','encodingSource','Halo 7 MIT!',6)+actions(btn('Konversi','runEncoding',true),btn('Salin hasil','copyEncoding'))+result());let output='';on('runEncoding',()=>{try{const source=val('encodingSource'),mode=val('encodingMode');output=mode==='uriEncode'?encodeURIComponent(source):mode==='uriDecode'?decodeURIComponent(source):mode==='b64Encode'?encodeBase64(source):decodeBase64(source);q('#edResult').classList.add('everyday-code');textResult(output);}catch(e){output='';textResult('Input tidak sesuai operasi: '+e.message);}});on('copyEncoding',()=>copy(output));q('#runEncoding').click();});
function hexRGB(value){if(!/^#[a-f0-9]{6}$/i.test(value))throw Error('Gunakan kode warna #RRGGBB.');return [1,3,5].map(i=>parseInt(value.slice(i,i+2),16));}
function contrast(a,b){const lum=c=>{const v=hexRGB(c).map(n=>{const s=n/255;return s<=.04045?s/12.92:((s+.055)/1.055)**2.4;});return v[0]*.2126+v[1]*.7152+v[2]*.0722;};const x=lum(a),y=lum(b);return (Math.max(x,y)+.05)/(Math.min(x,y)+.05);}
function hslHex(h,s,l){s/=100;l/=100;const c=(1-Math.abs(2*l-1))*s,x=c*(1-Math.abs(h/60%2-1)),m=l-c/2;const rgb=h<60?[c,x,0]:h<120?[x,c,0]:h<180?[0,c,x]:h<240?[0,x,c]:h<300?[x,0,c]:[c,0,x];return '#'+rgb.map(v=>Math.round((v+m)*255).toString(16).padStart(2,'0')).join('');}
register('palette',body=>{intro(body,'Buat palet lima warna dan hitung rasio kontras antara dua kode warna. Klik warna untuk menyalin HEX.');body.insertAdjacentHTML('beforeend',select('Gaya palet','paletteMode',['Analog','Komplementer','Monokrom'])+actions(btn('Buat palet baru','makePalette',true))+'<div class="everyday-palette" id="paletteColors"></div>'+field('Warna teks (#RRGGBB)','contrastText','#24272b')+field('Warna latar (#RRGGBB)','contrastBackground','#ffffff')+actions(btn('Hitung kontras','checkContrast'))+result());function palette(){const base=randomInt(360),mode=val('paletteMode');const colors=Array.from({length:5},(_,i)=>hslHex((base+(mode==='Analog'?(i-2)*24:mode==='Komplementer'?i%2*180:0)+360)%360,mode==='Monokrom'?55:65,mode==='Monokrom'?20+i*14:35+i*8));q('#paletteColors').innerHTML=colors.map(color=>`<button class="everyday-swatch" data-color="${color}" style="background:${color};color:${contrast(color,'#ffffff')>contrast(color,'#111111')?'#ffffff':'#111111'}" aria-label="Salin warna ${color}">${color}</button>`).join('');body.querySelectorAll('[data-color]').forEach(b=>b.onclick=()=>copy(b.dataset.color));}function run(){try{const a=val('contrastText'),b=val('contrastBackground'),ratio=contrast(a,b);q('#edResult').style.color=a;q('#edResult').style.background=b;textResult('Rasio kontras: '+ratio.toFixed(2)+':1.');}catch(e){q('#edResult').style.removeProperty('color');q('#edResult').style.removeProperty('background');textResult(e.message);}}on('makePalette',palette);on('checkContrast',run);palette();run();});
register('image',body=>{intro(body,'Gambar diproses di browser dan tidak diunggah. Ubah ukuran, putar, lalu unduh PNG atau JPEG.');body.insertAdjacentHTML('beforeend','<input type="file" id="editorImageFile" accept="image/png,image/jpeg,image/webp" hidden>'+actions(btn('Pilih gambar','chooseEditorImage',true))+'<img id="editorImagePreview" class="everyday-image-preview" alt="Pratinjau gambar" hidden><div id="editorImageInfo" class="everyday-item-meta"></div><div class="everyday-row">'+field('Lebar (px)','editorWidth',800,'number')+field('Tinggi (px)','editorHeight',600,'number')+'</div><label><input type="checkbox" id="imageLock" checked> Pertahankan rasio</label>'+select('Format keluaran','imageFormat',[['image/png','PNG'],['image/jpeg','JPEG']])+'<label for="imageQuality">Kualitas JPEG: <span id="qualityValue">85</span>%</label><input id="imageQuality" type="range" min="20" max="100" value="85" class="study-slider">'+actions(btn('Putar 90°','rotateImage'),btn('Unduh gambar','downloadImage',true))+result());let image=null,angle=0,url=null;on('chooseEditorImage',()=>q('#editorImageFile').click());on('editorImageFile',()=>{const file=q('#editorImageFile').files[0];if(!file)return;if(file.size>25*1024*1024)return showToast('Pilih gambar maksimal 25 MB.');if(!['image/png','image/jpeg','image/webp'].includes(file.type))return showToast('Gunakan PNG, JPEG, atau WebP.');if(url)URL.revokeObjectURL(url);url=URL.createObjectURL(file);const img=new Image();img.onload=()=>{image=img;angle=0;q('#editorWidth').value=img.naturalWidth;q('#editorHeight').value=img.naturalHeight;q('#editorImagePreview').src=url;q('#editorImagePreview').hidden=false;q('#editorImageInfo').textContent=img.naturalWidth+' × '+img.naturalHeight+' px · '+(file.size/1024).toFixed(1)+' KB';textResult('Gambar siap diedit.');};img.onerror=()=>textResult('Gambar belum dapat dibaca.');img.src=url;},'change');for(const [id,other] of [['editorWidth','editorHeight'],['editorHeight','editorWidth']])on(id,()=>{if(image&&q('#imageLock').checked){const ratio=angle%180?image.naturalHeight/image.naturalWidth:image.naturalWidth/image.naturalHeight;q('#'+other).value=Math.max(1,Math.round(id==='editorWidth'?num(id)/ratio:num(id)*ratio));}},'input');on('imageQuality',()=>q('#qualityValue').textContent=val('imageQuality'),'input');on('rotateImage',()=>{if(!image)return showToast('Pilih gambar terlebih dahulu.');angle=(angle+90)%360;const w=val('editorWidth');q('#editorWidth').value=val('editorHeight');q('#editorHeight').value=w;q('#editorImagePreview').style.transform='rotate('+angle+'deg)';});on('downloadImage',()=>{if(!image)return showToast('Pilih gambar terlebih dahulu.');const width=num('editorWidth'),height=num('editorHeight');if(!Number.isInteger(width)||!Number.isInteger(height)||width<1||height<1||width>8192||height>8192||width*height>20000000)return textResult('Ukuran maksimal 8192 px per sisi dan 20 juta piksel total.');const canvas=document.createElement('canvas');canvas.width=width;canvas.height=height;const c=canvas.getContext('2d');if(val('imageFormat')==='image/jpeg'){c.fillStyle='#fff';c.fillRect(0,0,width,height);}c.translate(width/2,height/2);c.rotate(angle*Math.PI/180);const w=angle%180?height:width,h=angle%180?width:height;c.drawImage(image,-w/2,-h/2,w,h);canvas.toBlob(blob=>{if(!blob)return textResult('Gambar gagal diekspor.');const resultURL=URL.createObjectURL(blob),a=document.createElement('a');a.href=resultURL;a.download='gambar-7mit.'+(val('imageFormat')==='image/png'?'png':'jpg');a.click();textResult('Diekspor '+width+' × '+height+' px · '+(blob.size/1024).toFixed(1)+' KB.');setTimeout(()=>URL.revokeObjectURL(resultURL),1000);},val('imageFormat'),num('imageQuality')/100);});clean=()=>{if(url)URL.revokeObjectURL(url);};});
function markdown(text){let inCode=false;return text.split('\n').map(line=>{if(line.startsWith('```')){inCode=!inCode;return inCode?'<pre class="everyday-code"><code>':'</code></pre>';}if(inCode)return escape(line)+'\n';let safe=escape(line).replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>').replace(/`([^`]+)`/g,'<code>$1</code>').replace(/\*([^*]+)\*/g,'<em>$1</em>');if(/^### /.test(line))return '<h3>'+safe.slice(4)+'</h3>';if(/^## /.test(line))return '<h2>'+safe.slice(3)+'</h2>';if(/^# /.test(line))return '<h1>'+safe.slice(2)+'</h1>';if(/^[-*] /.test(line))return '<p>• '+safe.slice(2)+'</p>';if(/^> /.test(line))return '<blockquote>'+safe.slice(5)+'</blockquote>';return safe?'<p>'+safe+'</p>':'<br>';}).join('')+(inCode?'</code></pre>':'');}
register('markdown',body=>{intro(body,'Editor Markdown sederhana untuk judul, daftar, tebal, miring, kutipan, dan blok kode. Tersimpan otomatis di perangkat.');body.insertAdjacentHTML('beforeend',textarea('Markdown','markdownSource',data.markdown||'# Ide hari ini\n\nTulis **ide terbaikmu** di sini.',10)+actions(btn('Salin Markdown','copyMarkdown'),btn('Unduh .md','downloadMarkdown'))+'<h3>Pratinjau</h3><div id="markdownPreview" class="everyday-preview"></div>');function render(){data.markdown=val('markdownSource');save();q('#markdownPreview').innerHTML=markdown(data.markdown);}on('markdownSource',render,'input');on('copyMarkdown',()=>copy(val('markdownSource')));on('downloadMarkdown',()=>download('catatan.md',val('markdownSource'),'text/markdown;charset=utf-8'));render();});
function parseCSV(text){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++;}else if(!quoted&&cell.length)throw Error('Tanda kutip harus berada di awal sel.');else quoted=!quoted;}else if(c===','&&!quoted){row.push(cell);cell='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);rows.push(row);row=[];cell='';}else cell+=c;}if(quoted)throw Error('Tanda kutip belum ditutup.');if(cell.length||row.length){row.push(cell);rows.push(row);}return rows;}
function writeCSV(rows){return rows.map(row=>row.map(value=>{let s=String(value??'');if(typeof value!=='number'&&/^[=+\-@\t\r]/.test(s))s="'"+s;return /[",\r\n]/.test(s)?'"'+s.replace(/"/g,'""')+'"':s;}).join(',')).join('\r\n');}
register('csv',body=>{intro(body,'Impor CSV, edit sel, lalu ekspor. Data hanya diproses di perangkat. Maksimal 100 baris dan 15 kolom.');body.insertAdjacentHTML('beforeend',textarea('CSV sumber','csvSource','Nama,Jumlah\nContoh,1',4)+actions(btn('Muat tabel','loadCSV',true),btn('Tambah baris','addCSVRow'),btn('Tambah kolom','addCSVColumn'),btn('Unduh CSV','exportCSV'))+'<div class="everyday-table-wrap" id="csvTable"></div>'+result());let rows=[];function render(){const columns=Math.max(1,...rows.map(r=>r.length));q('#csvTable').innerHTML='<table class="everyday-table"><tbody>'+rows.map((row,i)=>'<tr>'+Array.from({length:columns},(_,j)=>`<td><input data-csv-row="${i}" data-csv-col="${j}" value="${escape(row[j]||'')}" aria-label="Baris ${i+1} kolom ${j+1}"></td>`).join('')+`<td><button class="everyday-subtle-button" data-csv-delete="${i}" aria-label="Hapus baris ${i+1}">×</button></td></tr>`).join('')+'</tbody></table>';body.querySelectorAll('[data-csv-row]').forEach(i=>i.oninput=()=>{rows[+i.dataset.csvRow][+i.dataset.csvCol]=i.value;});body.querySelectorAll('[data-csv-delete]').forEach(b=>b.onclick=()=>{rows.splice(+b.dataset.csvDelete,1);render();});textResult(rows.length+' baris · '+columns+' kolom.');}on('loadCSV',()=>{try{const parsed=parseCSV(val('csvSource'));if(parsed.length>100||parsed.some(r=>r.length>15))throw Error('Batas tabel 100 baris dan 15 kolom.');rows=parsed.length?parsed:[['']];render();}catch(e){textResult(e.message);}});on('addCSVRow',()=>{if(rows.length>=100)return showToast('Maksimal 100 baris.');rows.push(Array(Math.max(1,...rows.map(r=>r.length))).fill(''));render();});on('addCSVColumn',()=>{const count=Math.max(1,...rows.map(r=>r.length));if(count>=15)return showToast('Maksimal 15 kolom.');rows.forEach(r=>{while(r.length<count+1)r.push('');});render();});on('exportCSV',()=>download('tabel.csv',writeCSV(rows),'text/csv;charset=utf-8'));q('#loadCSV').click();});
register('itinerary',body=>{intro(body,'Susun aktivitas perjalanan berdasarkan tanggal dan waktu. Semua jadwal ini disimpan di perangkat.');body.insertAdjacentHTML('beforeend',field('Nama perjalanan','tripName',data.tripName||'Perjalanan baru')+field('Tanggal','tripDate',today(),'date')+field('Waktu (HH:MM)','tripTime','09:00')+field('Tempat','tripPlace')+textarea('Aktivitas & catatan','tripActivity','',3)+actions(btn('Tambah aktivitas','addTrip',true),btn('Unduh rencana','downloadTrip'))+'<div id="tripList"></div>');function list(){const sorted=data.trips.map((t,i)=>({...t,index:i})).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));bindList(q('#tripList'),sorted,t=>`<div class="everyday-list-item"><div><strong>${escape(t.place)}</strong><small>${escape(t.date)} · ${escape(t.time)}</small><p>${escape(t.activity)}</p></div><button class="everyday-subtle-button" data-trip-delete="${t.index}">Hapus</button></div>`);body.querySelectorAll('[data-trip-delete]').forEach(b=>b.onclick=()=>removeAt(data.trips,+b.dataset.tripDelete,list));}on('tripName',()=>{data.tripName=val('tripName');save();},'input');on('addTrip',()=>{if(!val('tripPlace').trim()||!val('tripDate')||!/^([01]\d|2[0-3]):[0-5]\d$/.test(val('tripTime')))return showToast('Isi tempat, tanggal, dan jam HH:MM yang valid.');data.trips.push({date:val('tripDate'),time:val('tripTime'),place:val('tripPlace').trim().slice(0,200),activity:val('tripActivity').slice(0,4000)});data.tripName=val('tripName');save();q('#tripPlace').value='';q('#tripActivity').value='';list();});on('downloadTrip',()=>download('rencana-perjalanan.txt',val('tripName')+'\n\n'+[...data.trips].sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time)).map(t=>t.date+' '+t.time+' · '+t.place+'\n'+t.activity).join('\n\n')));list();});
register('packing',body=>{intro(body,'Siapkan barang bawaan dan tandai yang sudah masuk tas.');body.insertAdjacentHTML('beforeend',select('Templat awal','packingTemplate',[['custom','Kosong / tambah sendiri'],['school','Kegiatan sekolah'],['overnight','Menginap'],['travel','Perjalanan']])+actions(btn('Tambahkan templat','applyPacking'))+field('Barang bawaan','packingName')+actions(btn('Tambah barang','addPacking',true),btn('Unduh checklist','downloadPacking'))+result()+'<div id="packingList"></div>');const templates={school:['Alat tulis','Buku catatan','Botol minum','Kartu identitas'],overnight:['Baju ganti','Perlengkapan mandi','Pakaian tidur','Pengisi daya'],travel:['Tiket / bukti reservasi','Kartu identitas','Pakaian','Perlengkapan mandi','Botol minum']};function list(){const done=data.packing.filter(i=>i.done).length;textResult(done+' dari '+data.packing.length+' barang siap.');bindList(q('#packingList'),data.packing,(t,i)=>`<div class="everyday-list-item ${t.done?'done':''}"><input type="checkbox" data-packed="${i}" ${t.done?'checked':''} aria-label="Sudah membawa ${escape(t.name)}"><span>${escape(t.name)}</span><button class="everyday-subtle-button" data-packing-delete="${i}">×</button></div>`);body.querySelectorAll('[data-packed]').forEach(c=>c.onchange=()=>{data.packing[+c.dataset.packed].done=c.checked;save();list();});body.querySelectorAll('[data-packing-delete]').forEach(b=>b.onclick=()=>removeAt(data.packing,+b.dataset.packingDelete,list));}on('applyPacking',()=>{for(const name of templates[val('packingTemplate')]||[]){if(!data.packing.some(i=>i.name.toLowerCase()===name.toLowerCase()))data.packing.push({name,done:false});}save();list();});on('addPacking',()=>{if(!val('packingName').trim())return;data.packing.push({name:val('packingName').trim().slice(0,150),done:false});save();q('#packingName').value='';list();});on('downloadPacking',()=>download('daftar-bawaan.txt',data.packing.map(t=>(t.done?'[x] ':'[ ] ')+t.name).join('\n')));list();});
register('snippets',body=>{intro(body,'Simpan potongan teks yang sering dipakai, lalu salin atau masukkan ke draf chat.');body.insertAdjacentHTML('beforeend',field('Judul','snippetTitle')+textarea('Isi teks','snippetText','',5)+actions(btn('Simpan teks','saveSnippet',true))+'<div id="snippetsList"></div>');function list(){bindList(q('#snippetsList'),data.snippets,(s,i)=>`<section class="study-card"><h3>${escape(s.title)}</h3><p style="white-space:pre-wrap">${escape(s.text)}</p><div class="everyday-actions"><button class="study-button" data-snippet-copy="${i}">Salin</button><button class="study-button" data-snippet-draft="${i}">Ke draf chat</button><button class="everyday-subtle-button" data-snippet-remove="${i}">Hapus</button></div></section>`);body.querySelectorAll('[data-snippet-copy]').forEach(b=>b.onclick=()=>copy(data.snippets[+b.dataset.snippetCopy].text));body.querySelectorAll('[data-snippet-draft]').forEach(b=>b.onclick=()=>{els.input.value=data.snippets[+b.dataset.snippetDraft].text.slice(0,12000);autoResize();if(innerWidth<760)q('.study-panel').classList.remove('open');els.input.focus();showToast('Teks masuk ke draf. Periksa lalu kirim jika siap.');});body.querySelectorAll('[data-snippet-remove]').forEach(b=>b.onclick=()=>removeAt(data.snippets,+b.dataset.snippetRemove,list));}on('saveSnippet',()=>{if(!val('snippetTitle').trim()||!val('snippetText').trim())return showToast('Isi judul dan teks.');data.snippets.push({title:val('snippetTitle').trim().slice(0,100),text:val('snippetText').slice(0,12000)});save();q('#snippetTitle').value='';q('#snippetText').value='';list();});list();});
